47	/**
48	 * Interface for a service that prepares commands for sandboxed execution.
49	 */
50	export interface SandboxManager {
51	  /**
52	   * Prepares a command to run in a sandbox, including environment sanitization.
53	   */
54	  prepareCommand(req: SandboxRequest): Promise<SandboxedCommand>;
55	}
