111	export const NEVER_ALLOWED_NAME_PATTERNS = [
112	  /TOKEN/i,
113	  /SECRET/i,
114	  /PASSWORD/i,
115	  /PASSWD/i,
116	  /KEY/i,
117	  /AUTH/i,
118	  /CREDENTIAL/i,
119	  /CREDS/i,
120	  /PRIVATE/i,
121	  /CERT/i,
122	] as const;
